/* 로그인 이력관리 (7021) */
/* AdminLogLoginMapper.insert */
INSERT INTO CSPD810TH (
	AI_INPT_LGIN_HST_NO
	, AI_INPT_LGIN_USER_NO
	, AI_INPT_LGIN_DTM
	, AI_INPT_LGIN_USG_IPAD
	, AI_INPT_LGIN_USER_MCHR_NM
	, TRN_LOG_SRNO
	, LST_DB_CHG_ID
	, LST_DB_CHG_DTM
	, AI_INPT_LGIN_YN
) VALUES (

	, #{aiInptLginUserNo}
	, 
	, #{aiInptLginUsgIpad}

	, SUBSTR(#{aiInptLginUserMchrNm},1,190)
	, TO_CHAR(SYSDATE,'YYYYMMDD')||#{lstDbChgId}
	, #{lstDbChgId}
	, 
	, #{aiInptLginYn}
)
